const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

// Salva sessao se fez login
if (input.fezLogin && input.success && input.cookies) {
  staticData.cookies = input.cookies;
  staticData.localStorage = input.localStorage;
  staticData.ultimoLogin = new Date().toISOString();
  staticData.url = input.url;
}

// Limpa se expirou
if (input.sessaoExpirada) {
  staticData.cookies = [];
  staticData.localStorage = {};
  staticData.ultimoLogin = null;
}

const log = (input.log || []).join('\n');
const texto = `*COTADOR HAPVIDA*\n\nStatus: ${input.success ? 'SUCESSO' : 'ERRO'}\nErro: ${input.error || 'Nenhum'}\n\nLog:\n${log}\n\nURL: ${input.url || ''}`;

return [{ json: { number: '5583999471031', text: texto } }];
